declare(strict_types=1);require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';require_once __DIR__.'/noa-bridge/catalog-recovery.php';lab_admin();header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');
