try{$db=noa_bridge_pdo();if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['noa_lab_csrf'],(string)($_POST['csrf']??'')))throw new DomainException('csrf_invalid');
 if(($_POST['action']??'')==='prepare'){$plan=nr_plan($db);nr_save($plan);}
 elseif(($_POST['action']??'')==='apply'){$plan=nr_load((string)($_POST['plan']??''));$result=nr_apply($db,$plan,(string)$member['mb_id']);}
 else throw new InvalidArgumentException('invalid_action');
}}catch(Throwable $e){$error=$e instanceof DomainException||$e instanceof InvalidArgumentException?$e->getMessage():'복구 처리 실패 · 기존 자료는 유지됩니다.';error_log('[noa-recovery] '.get_class($e).':'.$e->getMessage());}
function nre(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
